"""
Task 010 — Simple filter expression evaluator

Implements evaluate(expr, record) -> bool
Parses and evaluates a simple filter expression against a flat dict record.
"""

import re


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

# Token types
TK_AND   = 'AND'
TK_OR    = 'OR'
TK_NOT   = 'NOT'
TK_LPAREN = 'LPAREN'
TK_RPAREN = 'RPAREN'
TK_OP    = 'OP'
TK_FIELD = 'FIELD'
TK_NUM   = 'NUM'
TK_STR   = 'STR'
TK_EOF   = 'EOF'

_TOKEN_RE = re.compile(
    r'\s*(?:'
    r'(AND|OR|NOT)(?![a-zA-Z0-9_])'   # keywords (must not be part of identifier)
    r'|([a-zA-Z][a-zA-Z0-9_]*)'        # identifier / field
    r'|(>=|<=|!=|==|>|<)'              # operators
    r"|'([^']*)'"                       # single-quoted string
    r'|(-?\d+(?:\.\d+)?)'              # number (int or float)
    r'|(\()'                            # left paren
    r'|(\))'                            # right paren
    r')\s*',
    re.ASCII
)


def tokenize(expr: str):
    """Return list of (token_type, value) pairs."""
    tokens = []
    pos = 0
    length = len(expr)
    while pos < length:
        # Skip whitespace
        if expr[pos].isspace():
            pos += 1
            continue
        m = _TOKEN_RE.match(expr, pos)
        if not m:
            raise ValueError(f"Unexpected character at position {pos}: {expr[pos]!r}")
        keyword, ident, op, string, number, lparen, rparen = m.groups()
        if keyword is not None:
            tokens.append((keyword, keyword))  # TK_AND, TK_OR, TK_NOT
        elif ident is not None:
            tokens.append((TK_FIELD, ident))
        elif op is not None:
            tokens.append((TK_OP, op))
        elif string is not None:
            tokens.append((TK_STR, string))
        elif number is not None:
            # Parse as int or float
            if '.' in number:
                tokens.append((TK_NUM, float(number)))
            else:
                tokens.append((TK_NUM, int(number)))
        elif lparen is not None:
            tokens.append((TK_LPAREN, '('))
        elif rparen is not None:
            tokens.append((TK_RPAREN, ')'))
        pos = m.end()
    tokens.append((TK_EOF, None))
    return tokens


# ---------------------------------------------------------------------------
# Parser (recursive descent)
# ---------------------------------------------------------------------------

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def consume(self, expected_type=None, expected_val=None):
        tok = self.tokens[self.pos]
        if expected_type and tok[0] != expected_type:
            raise ValueError(
                f"Expected token {expected_type!r} but got {tok[0]!r} ({tok[1]!r})"
            )
        if expected_val and tok[1] != expected_val:
            raise ValueError(
                f"Expected {expected_val!r} but got {tok[1]!r}"
            )
        self.pos += 1
        return tok

    def parse_expr(self):
        node = self.parse_or_expr()
        # After parsing the full expression, we should be at EOF
        if self.peek()[0] != TK_EOF:
            raise ValueError(
                f"Unexpected token after expression: {self.peek()[1]!r}"
            )
        return node

    def parse_or_expr(self):
        left = self.parse_and_expr()
        while self.peek()[0] == TK_OR:
            self.consume()  # consume OR
            right = self.parse_and_expr()
            left = ('OR', left, right)
        return left

    def parse_and_expr(self):
        left = self.parse_not_expr()
        while self.peek()[0] == TK_AND:
            self.consume()  # consume AND
            right = self.parse_not_expr()
            left = ('AND', left, right)
        return left

    def parse_not_expr(self):
        if self.peek()[0] == TK_NOT:
            self.consume()  # consume NOT
            operand = self.parse_not_expr()
            return ('NOT', operand)
        return self.parse_comparison()

    def parse_comparison(self):
        tok = self.peek()
        if tok[0] == TK_LPAREN:
            self.consume()  # consume '('
            node = self.parse_or_expr()
            if self.peek()[0] != TK_RPAREN:
                raise ValueError(
                    f"Expected ')' but got {self.peek()[1]!r}"
                )
            self.consume()  # consume ')'
            return node
        # Must be a field comparison
        if tok[0] != TK_FIELD:
            raise ValueError(
                f"Expected field name or '(' but got {tok[0]!r} ({tok[1]!r})"
            )
        field_tok = self.consume(TK_FIELD)
        field = field_tok[1]

        if self.peek()[0] != TK_OP:
            raise ValueError(
                f"Expected comparison operator after field {field!r}, "
                f"got {self.peek()[1]!r}"
            )
        op_tok = self.consume(TK_OP)
        op = op_tok[1]

        val_tok = self.peek()
        if val_tok[0] == TK_NUM:
            self.consume()
            value = val_tok[1]
        elif val_tok[0] == TK_STR:
            self.consume()
            value = val_tok[1]
        else:
            raise ValueError(
                f"Expected number or quoted string as value, got {val_tok[1]!r}"
            )

        return ('CMP', field, op, value)


# ---------------------------------------------------------------------------
# Evaluator
# ---------------------------------------------------------------------------

def _eval_node(node, record: dict) -> bool:
    kind = node[0]

    if kind == 'OR':
        _, left, right = node
        return _eval_node(left, record) or _eval_node(right, record)

    if kind == 'AND':
        _, left, right = node
        return _eval_node(left, record) and _eval_node(right, record)

    if kind == 'NOT':
        _, operand = node
        return not _eval_node(operand, record)

    if kind == 'CMP':
        _, field, op, value = node
        if field not in record:
            raise KeyError(field)
        field_val = record[field]

        # Type checking
        if isinstance(value, (int, float)):
            if not isinstance(field_val, (int, float)):
                raise TypeError(
                    f"Cannot compare {type(field_val).__name__} with numeric value"
                )
        elif isinstance(value, str):
            if not isinstance(field_val, str):
                raise TypeError(
                    f"Cannot compare {type(field_val).__name__} with string value"
                )
        else:
            raise TypeError(f"Unsupported value type: {type(value)}")

        if op == '==':
            return field_val == value
        elif op == '!=':
            return field_val != value
        elif op == '>':
            return field_val > value
        elif op == '<':
            return field_val < value
        elif op == '>=':
            return field_val >= value
        elif op == '<=':
            return field_val <= value
        else:
            raise ValueError(f"Unknown operator: {op}")

    raise ValueError(f"Unknown AST node type: {kind}")


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def evaluate(expr: str, record: dict) -> bool:
    """
    Parse and evaluate a simple filter expression against a single record
    (a flat dict). Returns True if the record matches.

    Raises:
        ValueError: on syntax errors
        KeyError: if a referenced field is not in the record
        TypeError: if types are incompatible for comparison
    """
    tokens = tokenize(expr)
    parser = Parser(tokens)
    ast = parser.parse_expr()
    return _eval_node(ast, record)
